 * Parsing of the election input format described in the task: a
 * `candidates` line followed by any number of `ballot` lines, blank
 * lines and `#` comments.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

class ParseError extends Error {
  constructor(message) {
    super(message)
  }
}

function fail(line, message) {
  throw new ParseError(line === null ? `error: ${message}` : `error: line ${line}: ${message}`)
}

/**
 * Parses the raw input text into a list of candidate names (in
 * declaration order) and a list of ballots, each `{ count, ranking }`.
 * Throws a `ParseError` carrying the exact message to print on failure.
 */
function parseElection(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) fail(lineNumber, 'candidates must be declared once, before any ballot')
      if (tokens.length < 2) fail(lineNumber, 'expected candidates <name>...')
      const names = tokens.slice(1)
      for (const name of names) {
        if (!NAME_RE.test(name)) fail(lineNumber, `invalid candidate name ${name}`)
        if (candidateSet.has(name)) fail(lineNumber, `candidate ${name} is declared twice`)
        candidateSet.add(name)
      }
      candidates = names
    } else if (word === 'ballot') {
      if (candidates === null) fail(lineNumber, 'candidates must be declared once, before any ballot')
      if (tokens.length < 3) fail(lineNumber, 'expected ballot <count> <candidate>...')
      const countText = tokens[1]
      if (!COUNT_RE.test(countText)) fail(lineNumber, 'count must be a positive integer')
      const count = Number(countText)
      const ranking = tokens.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!candidateSet.has(name)) fail(lineNumber, `unknown candidate ${name}`)
        if (seen.has(name)) fail(lineNumber, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count, ranking })
    } else {
      fail(lineNumber, `unknown directive ${word}`)
    }
  }

  if (candidates === null) fail(null, 'no candidates')

  return { candidates, ballots }
}

export { parseElection, ParseError }
"}

