{"file_path":"src/election.js","content":"/**
 * Instant-runoff counting: turns a parsed election into the sequence of
 * rounds the task describes, including the elimination tie-break rule.
 */

/**
 * Picks which of the tied-for-fewest candidates to eliminate. `tied` is
 * the list of candidate names sharing the minimum vote count in the
 * current (last) round. `history` is the list of round vote maps, one
 * per round counted so far including the current round, each mapping
 * every candidate continuing in that round to its vote count.
 */
function breakTie(tied, history) {
  let survivors = tied
  let roundIndex = 0
  while (survivors.length > 1 && roundIndex < history.length) {
    const votes = survivors.map((name) => history[roundIndex].get(name))
    const allEqual = votes.every((v) => v === votes[0])
    if (!allEqual) {
      const min = Math.min(...votes)
      survivors = survivors.filter((name) => history[roundIndex].get(name) === min)
      roundIndex = 0
    } else {
      roundIndex += 1
    }
  }
  if (survivors.length > 1) {
    survivors = [...survivors].sort()
    return survivors[survivors.length - 1]
  }
  return survivors[0]
}

/**
 * Runs the full instant-runoff count. Returns `{ rounds, winner }`
 * where `rounds` is a list of `{ votes, exhausted, eliminated }` and
 * `votes` is a list of `{ name, count }` sorted by descending count
 * then ascending name. `eliminated` is `null` for the final round.
 * `winner` is the winning candidate name, or `null` if none.
 */
function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)
    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    const sorted = [...votes.entries()]
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

    if (activeTotal === 0) {
      rounds.push({ votes: sorted, exhausted, eliminated: null })
      break
    }

    const majority = sorted.find((entry) => entry.count * 2 > activeTotal)
    if (majority !== undefined) {
      rounds.push({ votes: sorted, exhausted, eliminated: null })
      winner = majority.name
      break
    }

    const fewest = Math.min(...sorted.map((entry) => entry.count))
    const tied = sorted.filter((entry) => entry.count === fewest).map((entry) => entry.name)
    const eliminated = breakTie(tied, history)
    continuing.delete(eliminated)

    rounds.push({ votes: sorted, exhausted, eliminated })
  }

  return { rounds, winner }
}

export { runElection }
"}

