{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = readStdin()

  let candidates, ballots
  try {
    ;({ candidates, ballots } = parseElection(input))
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(err.message + '\n')
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = runElection(candidates, ballots)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.votes.map((entry) => `${entry.name}=${entry.count}`)
      parts.push(`exhausted=${round.exhausted}`)
      output.push(`round ${index + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) output.push(`eliminated ${round.eliminated}`)
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
}

main()
